public static class ProductApiPage
{
 public static string Html()=>Membership.Shell("Yapay zekâ API ayarı","""
 <section class="member-card"><p class="member-eyebrow">SUNUCU BAĞLANTILARI</p><h1>Yapay zekâ API</h1><p>Anahtarı bir kez kaydedin. Tüm ürünlerde aynı sunucu bağlantısı kullanılır; her fotoğraf için yeniden girilmez.</p>
 <div style="padding:14px;border:1px solid #d7e4ec;border-radius:14px;background:#f4f8fc;margin:16px 0"><strong>OpenAI</strong><p id="api-state" role="status">Bağlantı durumu alınıyor…</p><small>Ürün görsellerinden açıklama hazırlamak için kullanılır. API kullanımı sağlayıcı hesabınızın tarifesine tabidir.</small></div>
 <form id="api-form"><label>API anahtarı<input id="api-key" type="password" autocomplete="new-password" minlength="20" maxlength="300" placeholder="Yeni anahtarı buraya girin" required></label><p class="muted">Kayıtlı anahtar güvenlik nedeniyle gösterilmez. Değiştirmek için yeni anahtarı yazıp kaydedin. Boş alan mevcut anahtarı silmez.</p><div class="member-actions"><button id="api-save" class="member-button" type="submit">API anahtarını kaydet</button><button id="api-remove" class="member-secondary" type="button" hidden>Bağlantıyı kaldır</button></div></form>
 <p id="api-result" role="status" aria-live="polite"></p><p class="muted">Anahtar sunucuda şifreli saklanır. Bu bağlantı canlı destek çevirisiyle ortaktır. Bağlantı kaldırılırsa ürün eklemedeki yapay zekâ alanı gizlenir; kayıtlı açıklamalar korunur.</p><div class="member-actions"><a class="member-secondary" href="/admin?tab=settings">Ayarlara dön</a><a class="member-secondary" href="/admin?tab=products">Ürünlere git</a></div></section>
 <script>
 (()=>{const key=document.getElementById('api-key'),save=document.getElementById('api-save'),remove=document.getElementById('api-remove'),result=document.getElementById('api-result'),state=document.getElementById('api-state');let working=false;
 async function load(){const r=await fetch('/api/admin/ai-settings',{cache:'no-store'});if(!r.ok)throw Error('Bağlantı ayarı alınamadı. Oturumunuzu kontrol edin.');const b=await r.json();state.textContent=b.ready?'API kayıtlı · Tüm ürünlerde kullanılmaya hazır':'API kayıtlı değil · Ürünlerde yapay zekâ alanı gizli';remove.hidden=!b.ready;save.textContent=b.ready?'API anahtarını değiştir':'API anahtarını kaydet';}
 async function change(body){if(working)return;working=true;save.disabled=true;remove.disabled=true;result.textContent='Kaydediliyor…';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const cr=await fetch('/api/security/csrf',{signal:controller.signal,cache:'no-store'});if(!cr.ok)throw Error('Oturumunuzu yenileyin.');const token=(await cr.json()).token;const r=await fetch('/api/admin/ai-settings',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','X-INOKSKAR-CSRF':token},body:JSON.stringify(body)});const b=await r.json();if(!r.ok)throw Error(b.error||'Bağlantı kaydedilemedi.');key.value='';await load();result.textContent=body.remove?'API bağlantısı kaldırıldı.':'API anahtarı kaydedildi. Yeni ürünlerde açıklama otomatik hazırlanır.';}catch(e){result.textContent=e.name==='AbortError'?'İşlem zaman aşımına uğradı. Tekrar deneyin.':e.message;}finally{clearTimeout(timer);working=false;save.disabled=false;remove.disabled=false;}}
 document.getElementById('api-form').onsubmit=e=>{e.preventDefault();void change({apiKey:key.value.trim(),remove:false});};remove.onclick=()=>{if(confirm('API bağlantısı kaldırılsın mı? Canlı destek çevirisi de kapanır; kayıtlı açıklamalar korunur.'))void change({remove:true});};load().catch(e=>{state.textContent=e.message;});})();
 </script>
 """,false,true);
}
